//! S04 diverse-fixture reader recomputation battery: independent recomputation
//! and explicit unsupported accounting over the frozen twelve-fixture set.
//!
//! Each positive fixture is pinned by sha256 and driven through the frozen
//! `source_package` substrate, the root-bound `reader_gate` and the independent
//! `reader_verifier`. Every per-fixture fragment/view/reference list below is a
//! **handwritten oracle** derived from the fixture XML and the pinned reader
//! contract (`reader_wordml_profile/v1`) — never generated by the code under
//! test. The nine positive fixtures must classify as `SupportedWordml`, gate
//! `Ok`, build, and verify; the three negative fixtures must capture and be
//! **refused** with their expected source class, so an unsupported source can
//! never be silently promoted into reader support.
//!
//! Non-claims: this battery is `[bounded]` to the twelve self-authored
//! non-legal synthetic fixtures in `fixtures/reader/diverse/`; it is not corpus
//! coverage, not source authenticity and not a legal-completeness claim. R1000
//! stays active. Raw decoded legal text is never logged.

use std::collections::HashSet;

use ln_decode::reader_contract::{
    check_fragment_span, ReaderSegmentKind, ReaderSemantic, ReaderViewKind,
};
use ln_decode::reader_gate::{classify_source, gate_reader, ReaderSourceClass};
use ln_decode::reader_projection::{
    build_projection, canonical_projection_bytes, ProjectedView, ReaderProjection, SegmentOrigin,
};
use ln_decode::reader_verifier::verify_projection;
use ln_decode::source_package::{capture, Limits, Record, TextRecord};

