fn positive(name: &str) -> &'static Fixture {
    POSITIVE
        .iter()
        .find(|fixture| fixture.file == name)
        .unwrap_or_else(|| panic!("positive fixture {name} is not declared"))
}

// ------------------------------------------------------------------ helpers #

fn capture_fixture(fixture: &Fixture) -> Vec<Record> {
    let package = capture(fixture.xml.as_bytes(), &Limits::default())
        .unwrap_or_else(|error| panic!("{} must capture: {error:?}", fixture.file));
    assert_eq!(
        package.manifest().source.sha256,
        fixture.sha256,
        "{} content changed; re-pin the sha256 and the handwritten oracle",
        fixture.file
    );
    package.records().to_vec()
}

fn build_fixture(fixture: &Fixture) -> (Vec<Record>, ReaderProjection) {
    let records = capture_fixture(fixture);
    let projection = build_projection(&records)
        .unwrap_or_else(|error| panic!("{} must project: {error:?}", fixture.file));
    (records, projection)
}

fn strings(values: &[&str]) -> Vec<String> {
    values.iter().map(|value| value.to_string()).collect()
}

fn view<'a>(
    projection: &'a ReaderProjection,
    kind: ReaderViewKind,
    element_ref: &str,
) -> &'a ProjectedView {
    projection
        .views
        .iter()
        .find(|view| view.kind == kind && view.element_ref.as_str() == element_ref)
        .unwrap_or_else(|| panic!("view {kind:?} {element_ref} missing"))
}

/// `tN` for a source segment, `derived:<kind>` for a rendered control.
fn segment_tokens(
    projection: &ReaderProjection,
    kind: ReaderViewKind,
    element_ref: &str,
) -> Vec<String> {
    view(projection, kind, element_ref)
        .segment_refs
        .iter()
        .map(|id| {
            let segment = projection
                .segments
                .iter()
                .find(|segment| &segment.id == id)
                .expect("segment ref must resolve");
            match segment.origin {
                SegmentOrigin::SourceFragment => segment
                    .fragment_ref
                    .as_ref()
                    .expect("source segment carries a fragment")
                    .as_str()
                    .to_string(),
                SegmentOrigin::Derived(kind) => format!("derived:{}", kind.as_str()),
            }
        })
        .collect()
}

/// `type@element_ref` for each reference owned by the view, in order.
fn reference_tokens(
    projection: &ReaderProjection,
    kind: ReaderViewKind,
    element_ref: &str,
) -> Vec<String> {
    view(projection, kind, element_ref)
        .reference_refs
        .iter()
        .map(|id| {
            let reference = projection
                .references
                .iter()
                .find(|reference| &reference.id == id)
                .expect("reference ref must resolve");
            format!(
                "{}@{}",
                reference.reference_type.as_str(),
                reference.element_ref.as_str()
            )
        })
        .collect()
}

/// `kind:element_ref` for each child view, in order.
fn child_tokens(projection: &ReaderProjection, parent: &ProjectedView) -> Vec<String> {
    parent
        .children
        .iter()
        .map(|id| {
            let child = projection.view(id).expect("child view must resolve");
            format!("{}:{}", child.kind.as_str(), child.element_ref.as_str())
        })
        .collect()
}

fn parent_token(projection: &ReaderProjection, view: &ProjectedView) -> Option<String> {
    view.parent_view.as_ref().map(|id| {
        let parent = projection.view(id).expect("parent view must resolve");
        format!("{}:{}", parent.kind.as_str(), parent.element_ref.as_str())
    })
}

fn derived_kinds(projection: &ReaderProjection) -> Vec<&'static str> {
    projection
        .segments
        .iter()
        .filter_map(|segment| match segment.origin {
            SegmentOrigin::Derived(kind) => Some(kind.as_str()),
            SegmentOrigin::SourceFragment => None,
        })
        .collect()
}

fn assert_view_segments(
    projection: &ReaderProjection,
    kind: ReaderViewKind,
    element_ref: &str,
    expected: &[&str],
) {
    assert_eq!(
        segment_tokens(projection, kind, element_ref),
        strings(expected),
        "segments for {kind:?} {element_ref}"
    );
}

fn text_record<'a>(records: &'a [Record], fragment: &str) -> &'a TextRecord {
    records
        .iter()
        .find_map(|record| match record {
            Record::Text(text) if text.id == fragment => Some(text),
            _ => None,
        })
        .unwrap_or_else(|| panic!("fragment {fragment} must name a substrate text record"))
}

fn text_count(records: &[Record]) -> usize {
    records
        .iter()
        .filter(|record| matches!(record, Record::Text(_)))
        .count()
}

/// Coverage is total, duplicate-free and dangling-free: every substrate text
/// record is referenced by exactly one source segment.
fn assert_coverage(fixture: &Fixture, records: &[Record], projection: &ReaderProjection) {
    let mut expected: Vec<String> = records
        .iter()
        .filter_map(|record| match record {
            Record::Text(text) => Some(text.id.clone()),
            Record::Element(_) => None,
        })
        .collect();
    let mut seen: HashSet<String> = HashSet::new();
    let mut fragments: Vec<String> = Vec::new();
    for segment in &projection.segments {
        let Some(fragment) = &segment.fragment_ref else {
            continue;
        };
        // Dangling-free: the fragment names a real substrate text record.
        let _ = text_record(records, fragment.as_str());
        assert!(
            seen.insert(fragment.as_str().to_string()),
            "{}: fragment {fragment} referenced twice",
            fixture.file
        );
        fragments.push(fragment.as_str().to_string());
    }
    fragments.sort_unstable();
    expected.sort_unstable();
    assert_eq!(
        fragments, expected,
        "{}: coverage must be total and duplicate-free",
        fixture.file
    );
}

/// Shared positive-fixture invariants: the independent verifier accepts the
/// untampered projection, every source segment carries a valid whole-fragment
/// span, every derived segment carries a rendered literal and no source span,
/// and every reference stays unresolved.
fn assert_positive_invariants(
    fixture: &Fixture,
    records: &[Record],
    projection: &ReaderProjection,
) {
    if let Err(findings) = verify_projection(projection, records) {
        panic!(
            "{}: untampered projection must verify: {findings:?}",
            fixture.file
        );
    }
    assert_coverage(fixture, records, projection);
    for segment in &projection.segments {
        match segment.origin {
            SegmentOrigin::SourceFragment => {
                assert_eq!(segment.segment_kind, ReaderSegmentKind::Text);
                let fragment = segment
                    .fragment_ref
                    .as_ref()
                    .expect("source segment carries a fragment");
                let text = text_record(records, fragment.as_str());
                let value = text.value.as_str();
                let span = segment
                    .span
                    .as_ref()
                    .expect("source segment carries a span");
                assert_eq!(span.fragment, *fragment, "{}", segment.id);
                assert_eq!(span.start, 0, "{}", segment.id);
                assert_eq!(span.end, value.len(), "{}", segment.id);
                check_fragment_span(value, span).expect("span must validate");
                assert_eq!(segment.slot, Some(text.slot), "{}", segment.id);
                assert_eq!(segment.chars, value.chars().count(), "{}", segment.id);
                assert_eq!(
                    segment.output_end - segment.output_start,
                    value.len(),
                    "{}",
                    segment.id
                );
            }
            SegmentOrigin::Derived(kind) => {
                assert_eq!(segment.segment_kind, ReaderSegmentKind::Derived);
                assert!(segment.fragment_ref.is_none(), "{}", segment.id);
                assert!(segment.slot.is_none(), "{}", segment.id);
                assert!(segment.span.is_none(), "{}", segment.id);
                assert_eq!(segment.semantic, ReaderSemantic::DerivedSeparator);
                assert!(segment.contextual, "{}", segment.id);
                assert_eq!(
                    segment.text.as_deref(),
                    Some(kind.literal()),
                    "{}",
                    segment.id
                );
                assert_eq!(
                    segment.chars,
                    kind.literal().chars().count(),
                    "{}",
                    segment.id
                );
            }
        }
    }
    for reference in &projection.references {
        assert!(
            !reference.resolved,
            "{}: reference {} must stay unresolved",
            fixture.file, reference.id
        );
    }
}

// ------------------------------------------------------------------- tests #

#[test]
fn diverse_directory_holds_exactly_twelve_xml_fixtures() {
    const DIR: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/reader/diverse");
    let mut names: Vec<String> = std::fs::read_dir(DIR)
        .expect("diverse fixture directory must exist")
        .filter_map(|entry| entry.ok())
        .map(|entry| entry.file_name().to_string_lossy().to_string())
        .filter(|name| name.ends_with(".xml"))
        .collect();
    names.sort();
    assert_eq!(
        names,
        strings(ALL_XML_NAMES),
        "the frozen diverse set must be exactly these twelve XML fixtures"
    );
}

#[test]
fn every_positive_fixture_classifies_gates_projects_and_verifies() {
    assert_eq!(POSITIVE.len(), 9, "nine positive fixtures");
    for fixture in POSITIVE {
        let records = capture_fixture(fixture);
        assert_eq!(
            classify_source(&records),
            ReaderSourceClass::SupportedWordml,
            "{} must classify as supported WordML",
            fixture.file
        );
        assert_eq!(
            gate_reader(&records),
            Ok(ReaderSourceClass::SupportedWordml),
            "{} must pass the gate",
            fixture.file
        );
        let projection = build_projection(&records)
            .unwrap_or_else(|error| panic!("{} must project: {error:?}", fixture.file));
        assert_positive_invariants(fixture, &records, &projection);

        // Canonical projection bytes and the content seal are stable across
        // independent rebuilds of the same captured substrate.
        let first = canonical_projection_bytes(&projection);
        let rebuilt = build_projection(&records).expect("rebuild must project");
        let second = canonical_projection_bytes(&rebuilt);
        assert_eq!(
            first, second,
            "{}: canonical bytes must be deterministic",
            fixture.file
        );
        assert!(first.ends_with('\n'), "{}: LF-terminated", fixture.file);

        let mut sealed = projection.clone();
        sealed.reseal();
        let mut rebuilt_sealed = rebuilt.clone();
        rebuilt_sealed.reseal();
        assert_eq!(
            sealed.content_hash(),
            rebuilt_sealed.content_hash(),
            "{}: content seal must be stable",
            fixture.file
        );
    }
}

#[test]
fn text_only_matches_handwritten_oracle() {
    let fixture = positive("text-only.xml");
    let (_records, projection) = build_fixture(fixture);
    assert_eq!(projection.views.len(), 1);
    assert_eq!(projection.segments.len(), 1);
    assert_eq!(projection.references.len(), 0);
    // <w:wordDocument>=e0, <w:body>=e1, <w:p>=e2, <w:r>=e3, <w:t>=e4/t0.
    assert_view_segments(&projection, ReaderViewKind::Paragraph, "e2", &["t0"]);
    let segment = &projection.segments[0];
    assert_eq!(segment.element_ref.as_str(), "e4");
    assert_eq!(segment.semantic, ReaderSemantic::Body);
    assert!(!segment.contextual);
}

#[test]
fn encoding_controls_and_multibyte_match_handwritten_oracle() {
    let fixture = positive("encoding.xml");
    let (records, projection) = build_fixture(fixture);
    assert_eq!(projection.views.len(), 3);
    assert_eq!(text_count(&records), 7, "seven source texts t0..t6");
    // Paragraph 1 carries a tab and a line break between literal strings.
    assert_view_segments(
        &projection,
        ReaderViewKind::Paragraph,
        "e2",
        &["t0", "derived:tab", "t1", "derived:line_break", "t2"],
    );
    // Paragraph 2 interleaves Cyrillic, a decomposed combining mark and an astral emoji.
    assert_view_segments(
        &projection,
        ReaderViewKind::Paragraph,
        "e9",
        &["t3", "t4", "t5"],
    );
    // Paragraph 3 carries a non-breaking space.
    assert_view_segments(&projection, ReaderViewKind::Paragraph, "e14", &["t6"]);
    assert_eq!(derived_kinds(&projection), ["tab", "line_break"]);

    let chars: Vec<usize> = (0..7)
        .map(|index| {
            let fragment = format!("t{index}");
            projection
                .segments
                .iter()
                .find(|segment| {
                    segment.fragment_ref.as_ref().map(|f| f.as_str()) == Some(fragment.as_str())
                })
                .expect("fragment must have a segment")
                .chars
        })
        .collect();
    // "Привет"=6, "мир"=3, "!"=1, "Ж"=1, "e\u{301}"=2, astral emoji=1, "NBSP:\u{a0}Mu"=8.
    assert_eq!(chars, [6, 3, 1, 1, 2, 1, 8]);
}

#[test]
fn controls_render_documented_controls_and_ignore_last_rendered_hint() {
    let fixture = positive("controls.xml");
    let (records, projection) = build_fixture(fixture);
    assert_eq!(projection.views.len(), 6, "six paragraphs");
    assert_eq!(text_count(&records), 12, "twelve source texts t0..t11");
    assert_eq!(projection.references.len(), 1);

    // page break, default/explicit line break, carriage return, tab.
    assert_view_segments(
        &projection,
        ReaderViewKind::Paragraph,
        "e2",
        &["t0", "derived:page_break", "t1"],
    );
    assert_view_segments(
        &projection,
        ReaderViewKind::Paragraph,
        "e7",
        &["t2", "derived:line_break", "t3"],
    );
    assert_view_segments(
        &projection,
        ReaderViewKind::Paragraph,
        "e12",
        &["t4", "derived:line_break", "t5"],
    );
    // <w:cr/> is a line break, not a distinct control.
    assert_view_segments(
        &projection,
        ReaderViewKind::Paragraph,
        "e17",
        &["t6", "derived:line_break", "t7"],
    );
    // <w:lastRenderedPageBreak/> is known WordML context but not a control: the
    // reader renders nothing and raises no reference for it (no invented break).
    assert_view_segments(&projection, ReaderViewKind::Paragraph, "e22", &["t8", "t9"]);
    assert!(reference_tokens(&projection, ReaderViewKind::Paragraph, "e22").is_empty());
    // A default <w:tab/> renders; the foreign <fx:tab/> is only a reference.
    assert_view_segments(
        &projection,
        ReaderViewKind::Paragraph,
        "e27",
        &["t10", "derived:tab", "t11"],
    );
    assert_eq!(
        reference_tokens(&projection, ReaderViewKind::Paragraph, "e27"),
        strings(&["foreign_element@e30"])
    );
    assert_eq!(
        derived_kinds(&projection),
        [
            "page_break",
            "line_break",
            "line_break",
            "line_break",
            "tab"
        ],
        "exactly the five documented controls render; the last-rendered hint does not"
    );
}

#[test]
fn empty_structure_preserves_empty_views() {
    let fixture = positive("empty-structure.xml");
    let (_records, projection) = build_fixture(fixture);
    assert_eq!(projection.views.len(), 7);
    assert_eq!(projection.segments.len(), 1);
    assert_eq!(projection.references.len(), 0);

    // Two empty paragraphs survive as empty primary views, not dropped.
    let empty_paragraph = view(&projection, ReaderViewKind::Paragraph, "e2");
    assert!(empty_paragraph.flags.empty);
    assert!(empty_paragraph.segment_refs.is_empty());
    assert!(
        view(&projection, ReaderViewKind::Paragraph, "e3")
            .flags
            .empty
    );

    // An empty cell survives and is flagged empty; a sibling cell carries a paragraph.
    let table = view(&projection, ReaderViewKind::Table, "e4");
    let row = view(&projection, ReaderViewKind::Row, "e5");
    let empty_cell = view(&projection, ReaderViewKind::Cell, "e6");
    let full_cell = view(&projection, ReaderViewKind::Cell, "e7");
    assert_eq!(child_tokens(&projection, table), strings(&["row:e5"]));
    assert_eq!(parent_token(&projection, row).as_deref(), Some("table:e4"));
    assert_eq!(
        child_tokens(&projection, row),
        strings(&["cell:e6", "cell:e7"])
    );
    assert!(empty_cell.flags.empty);
    assert!(!full_cell.flags.empty);
    assert_eq!(
        child_tokens(&projection, full_cell),
        strings(&["paragraph:e8"])
    );
    assert_view_segments(&projection, ReaderViewKind::Paragraph, "e8", &["t0"]);
    assert!(
        !view(&projection, ReaderViewKind::Paragraph, "e8")
            .flags
            .empty
    );
    // Navigation views are never flagged empty when they hold children.
    assert!(!table.flags.empty);
    assert!(!row.flags.empty);
}

#[test]
fn notes_nested_attach_to_nearest_container() {
    let fixture = positive("notes-nested.xml");
    let (records, projection) = build_fixture(fixture);
    assert_eq!(projection.views.len(), 19);
    assert_eq!(text_count(&records), 5, "five source texts t0..t4");
    assert_eq!(projection.references.len(), 0);

    // A note defined in a cell attaches to that cell (not to the table root).
    let cell = view(&projection, ReaderViewKind::Cell, "e4");
    let note_in_cell = view(&projection, ReaderViewKind::Note, "e8");
    assert_eq!(
        child_tokens(&projection, cell),
        strings(&["paragraph:e5", "note:e8"])
    );
    assert_eq!(
        parent_token(&projection, note_in_cell).as_deref(),
        Some("cell:e4")
    );
    assert_view_segments(&projection, ReaderViewKind::Paragraph, "e5", &["t0"]);
    assert_view_segments(&projection, ReaderViewKind::Paragraph, "e9", &["t1"]);

    // A top-level note contains a nested table with a paragraph.
    let note_with_table = view(&projection, ReaderViewKind::Note, "e12");
    assert_eq!(parent_token(&projection, note_with_table), None);
    assert_eq!(
        child_tokens(&projection, note_with_table),
        strings(&["table:e13"])
    );
    assert_view_segments(&projection, ReaderViewKind::Paragraph, "e16", &["t2"]);

    // A cell inside a note also contains a paragraph.
    assert_view_segments(&projection, ReaderViewKind::Paragraph, "e23", &["t3"]);

    // A note nested inside a note attaches to the outer note.
    let outer_note = view(&projection, ReaderViewKind::Note, "e26");
    let inner_note = view(&projection, ReaderViewKind::Note, "e27");
    assert_eq!(
        child_tokens(&projection, outer_note),
        strings(&["note:e27"])
    );
    assert_eq!(
        parent_token(&projection, inner_note).as_deref(),
        Some("note:e26")
    );
    assert_view_segments(&projection, ReaderViewKind::Paragraph, "e28", &["t4"]);
}

#[test]
fn fields_revisions_keep_typed_references_and_revision_semantics() {
    let fixture = positive("fields-revisions.xml");
    let (_records, projection) = build_fixture(fixture);
    assert_eq!(projection.views.len(), 2);
    assert_eq!(projection.segments.len(), 3);
    assert_eq!(projection.references.len(), 3);

    // Field codes are retained but never trusted as body text: instrText owns a
    // field_code segment and every field element is a typed unresolved reference.
    assert_view_segments(&projection, ReaderViewKind::Paragraph, "e2", &["t0"]);
    assert_eq!(
        reference_tokens(&projection, ReaderViewKind::Paragraph, "e2"),
        strings(&["field@e4", "field@e6", "field@e8"])
    );
    assert_eq!(projection.segments[0].semantic, ReaderSemantic::FieldCode);
    assert!(projection.segments[0].contextual);

    // The revision pair keeps insertion and deletion ownership distinct.
    assert_view_segments(&projection, ReaderViewKind::Paragraph, "e9", &["t1", "t2"]);
    assert_eq!(
        projection.segments[1].semantic,
        ReaderSemantic::RevisionInsertion
    );
    assert_eq!(
        projection.segments[2].semantic,
        ReaderSemantic::RevisionDeletion
    );
    assert!(projection.segments[1].contextual && projection.segments[2].contextual);
}

#[test]
fn unknown_wordml_elements_stay_typed_references() {
    let fixture = positive("unknown-wordml.xml");
    let (records, projection) = build_fixture(fixture);
    assert_eq!(projection.views.len(), 2, "unknown elements create no view");
    assert_eq!(projection.segments.len(), 3);
    assert_eq!(text_count(&records), 3);

    // An invented pageBreak never renders as a page break; it stays a reference
    // and does not split the surrounding paragraph text.
    assert_view_segments(&projection, ReaderViewKind::Paragraph, "e2", &["t0", "t1"]);
    assert_eq!(
        reference_tokens(&projection, ReaderViewKind::Paragraph, "e2"),
        strings(&["unknown_wordml_element@e5"])
    );
    // A mystery wrapper is likewise a reference, not a control.
    assert_view_segments(&projection, ReaderViewKind::Paragraph, "e7", &["t2"]);
    assert_eq!(
        reference_tokens(&projection, ReaderViewKind::Paragraph, "e7"),
        strings(&["unknown_wordml_element@e10"])
    );
    // No view is anchored at the unknown elements themselves.
    for element_ref in ["e5", "e10"] {
        assert!(
            !projection
                .views
                .iter()
                .any(|view| view.element_ref.as_str() == element_ref),
            "unknown element {element_ref} must not be promoted to a view"
        );
    }
    let types: HashSet<&str> = projection
        .references
        .iter()
        .map(|reference| reference.reference_type.as_str())
        .collect();
    assert_eq!(types, HashSet::from(["unknown_wordml_element"]));
}

#[test]
fn note_reference_is_typed_unresolved_and_not_a_view() {
    // The frozen diverse set exercises field, unknown-wordml and foreign
    // references but carries no reference element (its notes are definitions), so
    // the closed reference-type list is completed here with an inline
    // self-authored non-legal synthetic fragment. <w:wordDocument>=e0,
    // <w:body>=e1, <w:p>=e2, <w:r>=e3, <w:t>=e4/t0, <w:footnoteReference>=e5.
    const XML: &str = concat!(
        r#"<w:wordDocument xmlns:w="http://schemas.microsoft.com/office/word/2003/wordml">"#,
        r#"<w:body><w:p><w:r><w:t>X</w:t><w:footnoteReference w:id="1"/></w:r></w:p></w:body>"#,
        r#"</w:wordDocument>"#
    );
    let package =
        capture(XML.as_bytes(), &Limits::default()).expect("inline fragment must capture");
    let records = package.records().to_vec();
    assert_eq!(
        classify_source(&records),
        ReaderSourceClass::SupportedWordml
    );
    assert_eq!(
        gate_reader(&records),
        Ok(ReaderSourceClass::SupportedWordml)
    );
    let projection = build_projection(&records).expect("inline fragment must project");
    assert!(verify_projection(&projection, &records).is_ok());
    assert_view_segments(&projection, ReaderViewKind::Paragraph, "e2", &["t0"]);
    assert_eq!(
        reference_tokens(&projection, ReaderViewKind::Paragraph, "e2"),
        strings(&["note_reference@e5"])
    );
    assert!(!projection.references[0].resolved);
    assert!(
        !projection
            .views
            .iter()
            .any(|view| view.element_ref.as_str() == "e5"),
        "a note reference must not be promoted to a view"
    );
}

#[test]
fn residual_and_tails_keep_residual_ownership() {
    let fixture = positive("residual-and-tails.xml");
    let (_records, projection) = build_fixture(fixture);
    assert_eq!(projection.views.len(), 7);
    assert_eq!(projection.segments.len(), 6);

    // Body-level residual text with no paragraph ancestor and a run-owned text
    // between it are anchored to the root residual in document-event order.
    assert_view_segments(
        &projection,
        ReaderViewKind::Residual,
        "e0",
        &["t0", "t1", "t2"],
    );
    // A cell tail after the paragraph is a residual view beside the paragraph
    // view on the same element; the paragraph keeps only its own text.
    let cell = view(&projection, ReaderViewKind::Cell, "e6");
    assert_eq!(
        child_tokens(&projection, cell),
        strings(&["paragraph:e7", "residual:e7"])
    );
    assert_view_segments(&projection, ReaderViewKind::Paragraph, "e7", &["t3"]);
    assert_view_segments(&projection, ReaderViewKind::Residual, "e7", &["t4"]);
    // A whitespace-only paragraph survives as a contextual whitespace segment.
    assert_view_segments(&projection, ReaderViewKind::Paragraph, "e10", &["t5"]);
    let whitespace = projection
        .segments
        .iter()
        .find(|segment| segment.fragment_ref.as_ref().map(|f| f.as_str()) == Some("t5"))
        .expect("whitespace segment");
    assert_eq!(whitespace.semantic, ReaderSemantic::Whitespace);
    assert!(whitespace.contextual);
}

#[test]
fn navigation_demo_combines_all_shapes() {
    let fixture = positive("navigation-demo.xml");
    let (records, projection) = build_fixture(fixture);
    assert_eq!(projection.views.len(), 27);
    assert_eq!(projection.segments.len(), 21);
    assert_eq!(projection.references.len(), 6);
    assert_eq!(text_count(&records), 19, "nineteen source texts t0..t18");

    // Two-by-two table with a cell-level tab.
    let table = view(&projection, ReaderViewKind::Table, "e5");
    assert_eq!(
        child_tokens(&projection, table),
        strings(&["row:e6", "row:e17"])
    );
    assert_view_segments(
        &projection,
        ReaderViewKind::Paragraph,
        "e12",
        &["t2", "derived:tab", "t3"],
    );
    // Documented page break.
    assert_view_segments(
        &projection,
        ReaderViewKind::Paragraph,
        "e26",
        &["t6", "derived:page_break", "t7"],
    );
    assert_eq!(derived_kinds(&projection), ["tab", "page_break"]);

    // Note contains a paragraph and a table; that table's cell holds a paragraph
    // and a nested note whose paragraph remains owned by the nested note.
    let note = view(&projection, ReaderViewKind::Note, "e31");
    assert_eq!(
        child_tokens(&projection, note),
        strings(&["paragraph:e32", "table:e35"])
    );
    let nested_note = view(&projection, ReaderViewKind::Note, "e41");
    let nested_cell = view(&projection, ReaderViewKind::Cell, "e37");
    assert_eq!(
        child_tokens(&projection, nested_cell),
        strings(&["paragraph:e38", "note:e41"])
    );
    assert_eq!(
        parent_token(&projection, nested_note).as_deref(),
        Some("cell:e37")
    );
    assert_view_segments(&projection, ReaderViewKind::Paragraph, "e42", &["t10"]);

    // Unknown wrappers, a field region and leftover body text with a foreign
    // element all keep their typed, unresolved treatment.
    assert_eq!(
        reference_tokens(&projection, ReaderViewKind::Paragraph, "e45"),
        strings(&["unknown_wordml_element@e47"])
    );
    assert_eq!(
        reference_tokens(&projection, ReaderViewKind::Paragraph, "e49"),
        strings(&["unknown_wordml_element@e51"])
    );
    assert_eq!(
        reference_tokens(&projection, ReaderViewKind::Paragraph, "e53"),
        strings(&["field@e55", "field@e57", "field@e59"])
    );
    assert_eq!(
        reference_tokens(&projection, ReaderViewKind::Residual, "e0"),
        strings(&["foreign_element@e66"])
    );
    assert_view_segments(&projection, ReaderViewKind::Residual, "e0", &["t16", "t18"]);

    let types: HashSet<&str> = projection
        .references
        .iter()
        .map(|reference| reference.reference_type.as_str())
        .collect();
    assert_eq!(
        types,
        HashSet::from(["foreign_element", "unknown_wordml_element", "field"])
    );
}

#[test]
fn negative_fixtures_are_refused_by_the_gate() {
    let expected = [
        (
            "negative-not-wordml.xml",
            ReaderSourceClass::SourceNotWordml,
        ),
        (
            "negative-unsupported-schema.xml",
            ReaderSourceClass::UnsupportedSchema,
        ),
        (
            "negative-namespace-absent.xml",
            ReaderSourceClass::NamespaceAbsent,
        ),
    ];
    for (file, class) in expected {
        let fixture = NEGATIVE
            .iter()
            .find(|fixture| fixture.file == file)
            .unwrap_or_else(|| panic!("negative fixture {file} is not declared"));
        let records = capture_fixture(fixture);
        // The substrate captures: the refusal is a reader-profile decision, not
        // a parse failure.
        assert_eq!(
            classify_source(&records),
            class,
            "{file} must classify as {class:?}"
        );
        let refusal = gate_reader(&records)
            .expect_err("an unsupported source must never be silently promoted");
        assert_eq!(refusal.kind(), class, "{file} refusal kind");
        assert!(
            !refusal.detail().is_empty(),
            "{file} refusal must carry a structural detail"
        );
        // Redaction: the refusal detail never quotes decoded source text.
        assert!(
            !refusal.detail().contains("Sample"),
            "{file} refusal must not leak decoded text"
        );
        // Gate evidence requires Ok; every negative class is closed.
        assert_ne!(class, ReaderSourceClass::SupportedWordml);
    }
}
